function canAliceWin(n) {
  // moverWins(left, need): the player who must now remove `need` of the `left` stones wins.
  // They lose at once if they cannot move; otherwise they win exactly when the opponent then loses.
  const moverWins = (left, need) => need > 0 && need <= left && !moverWins(left - need, need - 1);
  return moverWins(n, 10);
}

